prompt --application/shared_components/security/authentications/cleck_cloud1
begin
wwv_flow_api.create_authentication(
 p_id=>wwv_flow_api.id(9437432586655814)
,p_name=>'cleck_cloud1'
,p_scheme_type=>'NATIVE_CUSTOM'
,p_attribute_03=>'user_auth'
,p_attribute_05=>'N'
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'FUNCTION GETMD5(pstring IN VARCHAR2) RETURN VARCHAR2 IS',
'        hasil VARCHAR2(32) := '''';',
'BEGIN',
'        hasil := DBMS_OBFUSCATION_TOOLKIT.MD5(input => UTL_I18N.STRING_TO_RAW (pstring, ''AL32UTF8''));',
'        RETURN hasil;',
'END GETMD5;',
'',
'',
'',
'',
'FUNCTION user_auth    (',
'    ',
' p_username IN VARCHAR2, --User_Name',
' p_password IN VARCHAR2 -- Password    ',
')',
' RETURN BOOLEAN',
'AS',
' lc_pwd_exit VARCHAR2 (1);',
' HASHPASS VARCHAR2(32) := GETMD5(p_password);',
'BEGIN',
' -- Validate whether the user exits or not',
' SELECT ''1''',
' INTO lc_pwd_exit',
' FROM cleck_user',
' WHERE upper(USER_NAME) = UPPER (p_username) and upper(PASSWORD) = UPPER (HASHPASS) and (upper(USER_ROLE) = ''T''  OR upper(USER_ROLE) = ''A'')',
';',
'RETURN TRUE;',
'EXCEPTION',
' WHEN NO_DATA_FOUND',
' THEN',
' RETURN FALSE;',
'END user_auth;'))
,p_invalid_session_type=>'LOGIN'
,p_use_secure_cookie_yn=>'N'
,p_ras_mode=>0
);
end;
