'    null icon_color_class,',
'    case when nvl(:P2_PRODUCT_ID,''0'') = "PRODUCT_ID"',
'      then ''is-active'' ',
'      else '' ''',
'    end list_class,',
'    substr("PRODUCY_NAME", 1, 50)||( case when length("PRODUCY_NAME") > 50 then ''...'' end ) list_title,',
'    substr("PRODUCT_DESCRIPTION", 1, 50)||( case when length("PRODUCT_DESCRIPTION") > 50 then ''...'' end ) list_text,',
'    null list_badge',
'from "PRODUCT" x',
'where (:P2_SEARCH is null',
'        or upper(x."PRODUCY_NAME") like ''%''||upper(:P2_SEARCH)||''%''',
'        or upper(x."PRODUCT_DESCRIPTION") like ''%''||upper(:P2_SEARCH)||''%''',
'    )',
'      and fk1_shop_id IN (select shop_id from shop where fk1_user_id=(select USER_ID from cleck_user where UPPER(user_name)= UPPER(:APP_USER)))',
