,p_display_sequence=>20
,p_region_css_classes=>'search-results'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'t-MediaList--showDesc:t-MediaList--stack'
,p_display_point=>'REGION_POSITION_02'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select "USER_ID",',
'    null link_class,',
'    apex_page.get_url(p_items => ''P19_USER_ID'', p_values => "USER_ID") link,',
'    null icon_class,',
'    null link_attr,',
'    null icon_color_class,',
'    case when nvl(:P19_USER_ID,''0'') = "USER_ID"',
'      then ''is-active'' ',
'      else '' ''',
'    end list_class,',
'    substr("USER_FULLNAME", 1, 50)||( case when length("USER_FULLNAME") > 50 then ''...'' end ) list_title,',
'    substr("EMAIL", 1, 50)||( case when length("EMAIL") > 50 then ''...'' end ) list_text,',
'    null list_badge',
'from "CLECK_USER" x',
'where (:P19_SEARCH is null',
'        or upper(x."USER_FULLNAME") like ''%''||upper(:P19_SEARCH)||''%''',
'        or upper(x."EMAIL") like ''%''||upper(:P19_SEARCH)||''%''',
'    )',
'    and user_role=''C''',
'order by "USER_FULLNAME"'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P19_SEARCH'
,p_query_row_template=>wwv_flow_api.id(9356152893639581)
,p_query_num_rows=>1000
,p_query_options=>'DERIVED_REPORT_COLUMNS'
