'select "SHOP_ID",',
'    null link_class,',
'    apex_page.get_url(p_items => ''P37_SHOP_ID'', p_values => "SHOP_ID") link,',
'    null icon_class,',
'    null link_attr,',
'    null icon_color_class,',
'    case when nvl(:P37_SHOP_ID,''0'') = "SHOP_ID"',
'      then ''is-active'' ',
'      else '' ''',
'    end list_class,',
'    substr("SHOP_NAME", 1, 50)||( case when length("SHOP_NAME") > 50 then ''...'' end ) list_title,',
'    substr("SHOP_LOCATION", 1, 50)||( case when length("SHOP_LOCATION") > 50 then ''...'' end ) list_text,',
'    null list_badge',
'from "SHOP" x',
'where (:P37_SEARCH is null',
'        or upper(x."SHOP_NAME") like ''%''||upper(:P37_SEARCH)||''%''',
'        or upper(x."SHOP_LOCATION") like ''%''||upper(:P37_SEARCH)||''%''',
'    )',
'           and shop_id IN (select shop_id from shop where fk1_user_id=(select USER_ID from cleck_user where UPPER(user_name)= UPPER(:APP_USER)))',
'order by "SHOP_NAME"'))
